{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C67"],
      "claim": "Zalcitabine (ddC), a small polar nucleoside analogue, showed absolute oral bioavailability of 74% in patients, demonstrating that low lipophilicity does not preclude high oral absorption for this class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Lamivudine, a polar cytidine analogue with physicochemical properties similar to the query, has an absolute oral bioavailability of 87% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Emtricitabine, a fluorinated nucleoside analogue, has an absolute oral bioavailability of 93%, indicating that nucleobase fluorination is compatible with excellent absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Cladribine, a halogenated purine nucleoside, showed oral bioavailability of about 46%, still well above the 20% threshold, supporting high F for the purine nucleoside query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Didanosine showed only 17% oral bioavailability under fed conditions, but this low value is attributed to the acid-labile dideoxy sugar and food effects; the query contains a full ribose sugar and is unlikely to share this liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer nucleoside analogues (ddC, lamivudine, emtricitabine, cladribine) show absolute oral bioavailability ≥20%, often >80%, despite polar physicochemical properties. The only sub-20 value is didanosine under fed conditions due to acid-labile dideoxy sugar, a liability not shared by the ribose-containing query. Therefore the query is predicted to have high oral bioavailability at the F ≥20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for 2-amino-6-fluoropurine riboside.",
    "Acid stability of the ribose glycosidic bond and intestinal permeability of this specific nucleoside are not directly measured.",
    "Potential first-pass metabolism or transporter-mediated efflux for the query is not experimentally characterized.",
    "The didanosine fed-state low F may not transfer because of its dideoxy sugar acid lability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

